function csrf_input(): void { echo '<input type="hidden" name="csrf" value="' . e(csrf_token()) . '">'; }
function role_options(string $selected = 'content_editor'): void { foreach (ADMIN_ROLES as $value => $label) { echo '<option value="' . e($value) . '"' . ($selected === $value ? ' selected' : '') . '>' . e($label) . '</option>'; } }
